     1	/* https://leetcode.com/problems/longest-palindromic-substring/
     2	Given a string s, return the longest palindromic substring in s.
     3	
     4	Example 1:
     5	Input: s = "babad"
     6	Output: "bab"
     7	Explanation: "aba" is also a valid answer.
     8	*/
     9	
    10	
    11	// Specifying the problem: whether `s[i..j]` is palindromic
    12	ghost predicate palindromic(s: string, i: int, j: int)
    13	  requires 0 <= i <= j <= |s|
    14	  decreases j - i
    15	{
    16	  j - i < 2 || (s[i] == s[j-1] && palindromic(s, i+1, j-1))
    17	}
    18	
    19	// A "common sense" about palindromes:
    20	lemma lemma_palindromic_contains(s: string, lo: int, hi: int, lo': int, hi': int)
    21	  requires 0 <= lo <= lo' <= hi' <= hi <= |s|
    22	  requires lo + hi == lo' + hi'
    23	  requires palindromic(s, lo, hi)
    24	  ensures palindromic(s, lo', hi')
    25	  decreases lo' - lo
    26	{
    27	  if lo < lo' {
    28	    lemma_palindromic_contains(s, lo + 1, hi - 1, lo', hi');
    29	  }
    30	}
    31	
    32	// A useful "helper function" that returns the longest palindrome at a given center (i0, j0).
    33	method expand_from_center(s: string, i0: int, j0: int) returns (lo: int, hi: int)
    34	  requires 0 <= i0 <= j0 <= |s|
    35	  requires palindromic(s, i0, j0)
    36	  ensures 0 <= lo <= hi <= |s| && palindromic(s, lo, hi)
    37	  ensures forall i, j | 0 <= i <= j <= |s| && palindromic(s, i, j)  // Among all palindromes
    38	    && i + j == i0 + j0                                             // sharing the same center,
    39	    :: j - i <= hi - lo                                             // `s[lo..hi]` is longest.
    40	{
    41	  lo, hi := i0, j0;
    42	
    43	  // we try expanding whenever possible:
    44	  while lo - 1 >= 0 && hi < |s| && s[lo - 1] == s[hi]
    45	    invariant 0 <= lo <= hi <= |s| && lo + hi == i0 + j0
    46	    invariant palindromic(s, lo, hi)
    47	  {
    48	    lo, hi := lo - 1, hi + 1;
    49	  }
    50	
    51	  // proves that we cannot go further:
    52	  forall i, j | 0 <= i <= j <= |s| && i + j == i0 + j0 && j - i > hi - lo ensures !palindromic(s, i, j) {
    53	    if palindromic(s, i, j) { // prove by contradiction:
    54	      lemma_palindromic_contains(s, i, j, lo - 1, hi + 1);
    55	    }
    56	  }
    57	}
    58	
    59	
    60	// The main algorithm.
----
   200	  ensures |s'| == 2 * |s| + 1
   201	  ensures forall i | 0 <= i <= |s| :: s'[i * 2] == bogus
   202	  ensures forall i | 0 <= i < |s| :: s'[i * 2 + 1] == s[i]
   203	{
   204	  if s == "" then
   205	    [bogus]
   206	  else
   207	    var s'_old := insert_bogus_chars(s[1..], bogus);
   208	    var s'_new := [bogus] + [s[0]] + s'_old;
   209	    assert forall i | 1 <= i <= |s| :: s'_new[i * 2] == s'_old[(i-1) * 2];
   210	    s'_new
   211	}
   212	
   213	// Returns (max_index, max_value) of array `a` starting from index `start`.
   214	function {:opaque} argmax(a: array<int>, start: int): (res: (int, int))
   215	  reads a
   216	  requires 0 <= start < a.Length
   217	  ensures start <= res.0 < a.Length && a[res.0] == res.1
   218	  ensures forall i | start <= i < a.Length :: a[i] <= res.1
   219	  decreases a.Length - start
   220	{
   221	  if start == a.Length - 1 then
   222	    (start, a[start])
   223	  else
   224	    var (i, v) := argmax(a, start + 1);
   225	    if a[start] >= v then (start, a[start]) else (i, v)
   226	}
   227	
   228	// Whether an interval at center `c` with a radius `r` is within the boundary of `s'`.
   229	ghost predicate inbound_radius(s': string, c: int, r: int)
   230	{
   231	  r >= 0 && 0 <= c-r && c+r < |s'|
   232	}
   233	
   234	// Whether `r` is a valid palindromic radius at center `c`.
   235	ghost predicate palindromic_radius(s': string, c: int, r: int)
   236	  requires inbound_radius(s', c, r)
   237	{
   238	  palindromic(s', c-r, c+r+1)
   239	}
   240	
   241	// Whether `r` is the maximal palindromic radius at center `c`.
   242	ghost predicate max_radius(s': string, c: int, r: int)
   243	{
   244	  && inbound_radius(s', c, r)
   245	  && palindromic_radius(s', c, r)
   246	  && (forall r' | r' > r && inbound_radius(s', c, r') :: !palindromic_radius(s', c, r'))
   247	}
   248	
   249	// Basically, just "rephrasing" the `lemma_palindromic_contains`,
   250	// talking about center and radius, instead of interval
   251	lemma lemma_palindromic_radius_contains(s': string, c: int, r: int, r': int)
   252	  requires inbound_radius(s', c, r) && palindromic_radius(s', c, r)
   253	  requires 0 <= r' <= (r) + 1
   254	  ensures inbound_radius(s', c, r') && palindromic_radius(s', c, r')
   255	{
   256	  lemma_palindromic_contains(s', c-r, c+r+1, c-r', c+r'+1);
   257	}
   258	
   259	// When "expand from center" ends, we've find the max radius:
   260	lemma lemma_end_of_expansion(s': string, c: int, r: int)
   261	  requires inbound_radius(s', c, r) && palindromic_radius(s', c, r)
   262	  requires inbound_radius(s', c, r + 1) ==> s'[c - (r + 1)] != s'[c + (r + 1)]
   263	  ensures max_radius(s', c, r)
   264	{
   265	  forall r' | r' > r && inbound_radius(s', c, r') ensures !palindromic_radius(s', c, r') {
   266	    if palindromic_radius(s', c, r') {  // proof by contradiction
   267	      lemma_palindromic_radius_contains(s', c, r', r+1);
   268	    }
   269	  }
   270	}
   271	
   272	// The critical insight behind Manacher's algorithm.
   273	//
   274	// Given the longest palindrome centered at `c` has length `r`, consider the interval from `c-r` to `c+r`.
   275	// Consider a pair of centers in the interval: `c1` (left half) and `c2` (right half), equally away from `c`.
   276	// Then, the length of longest palindromes at `c1` and `c2` are related as follows:
   277	lemma lemma_mirrored_palindrome(s': string, c: int, r: int, c1: int, r1: int, c2: int)
   278	  requires max_radius(s', c, r) && max_radius(s', c1, r1)
   279	  requires c - r <= c1 < c < c2 <= c + r
   280	  requires c2 - c == c - c1
   281	  ensures c2 + r1 < c + r ==> max_radius(s', c2, r1)
   282	  ensures c2 + r1 > c + r ==> max_radius(s', c2, c + r - c2)
   283	  ensures c2 + r1 == c + r ==> palindromic_radius(s', c2, c + r - c2)
   284	{
   285	  // proof looks long, but is quite straightforward at each step:
   286	  if c2 + r1 < c + r {
   287	    for r2 := 0 to r1
   288	      invariant palindromic_radius(s', c2, r2)
   289	    {
   290	      var r2' := r2 + 1;
   291	      assert s'[c1+r2'] == s'[c2-r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 - r2')); }
   292	      assert s'[c1-r2'] == s'[c2+r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 + r2')); }
   293	      assert s'[c1-r2'] == s'[c1+r2'] by { lemma_palindromic_radius_contains(s', c1, r1, r2'); }
   294	    }
   295	    var r2' := r1 + 1;
   296	    assert s'[c1+r2'] == s'[c2-r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 - r2')); }
   297	    assert s'[c1-r2'] == s'[c2+r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 + r2')); }
   298	    assert s'[c1-r2'] != s'[c1+r2'] by { assert !palindromic_radius(s', c1, r2'); }
   299	    lemma_end_of_expansion(s', c2, r1);
   300	  } else {

